questions.body:
다음은 커서의 위치를 정하는 C 코드다. 이 코드의 보안약점과 대책에 대한 설명으로 옳지 않은 것은?

```c
int x, y;
switch(position) {
    case 0: x = base_position; y = base_position; break;
    case 1: x = base_position + i; y = base_position - i; break;
    default: x = 1; break;
}
setCursorPosition(x, y);
```

다음 C++ 코드의 변수(필드) 초기화에 대해 취약 여부를 판정하고, 취약하다면 취약 라인·근거·수정방안을 서술하시오.

```cpp
class Foo {
public:
    Foo() {}
    Foo(int a) : a_(a) {}
    int get_a() const { return a_; }
private:
    int a_;
};

int main(void) {
    Foo foo1;
    std::cout << foo1.get_a() << std::endl;
    return 0;
}
```

questions.vulnerable_code:
1  class Foo {
2  public:
3      Foo() {} // 디폴트 생성자, a_를 초기화하지 않음
4      Foo(int a) : a_(a) {} // 생성자
5      int get_a() const { return a_; }
6  private:
7      int a_;
8  };
9
10 int main(void) {
11     Foo foo1; // 디폴트 생성자 호출
12     std::cout << foo1.get_a() << std::endl;
13     return 0;
14 }

questions.safe_code:
1  class Foo {
2  public:
3      Foo() : a_(0) {} // 디폴트 생성자에서 a_를 0으로 초기화
4      Foo(int a) : a_(a) {}
5      int get_a() const { return a_; }
6  private:
7      int a_;
8  };
9
10 int main(void) {
11     Foo foo1;
12     std::cout << foo1.get_a() << std::endl;
13     return 0;
14 }

